// Prepare the result prompt: validate ids, format the booked slot for the user's locale (Europe/Berlin).
const b = $json.body || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID.test(String(b.call_id)) || !UUID.test(String(b.request_id))) throw new Error('invalid call_id/request_id');
const LANG = { en: 'English', ar: 'Arabic', tr: 'Turkish', uk: 'Ukrainian', ru: 'Russian', fa: 'Persian (Farsi)', prs: 'Dari (Afghan Persian)', hi: 'Hindi', es: 'Spanish', fr: 'French', pl: 'Polish', vi: 'Vietnamese', zh: 'Chinese (Simplified)', de: 'German' };
const LOCALE = { prs: 'fa-AF', fa: 'fa-IR', zh: 'zh-CN', hi: 'hi-IN', ar: 'ar', en: 'en-GB' };
const lang = LANG[b.user_language] ? b.user_language : 'en';
const locale = LOCALE[lang] || lang;
let slotUser = '', slotDe = '';
if (b.booked_slot) {
  const dt = DateTime.fromISO(String(b.booked_slot), { setZone: true }).setZone('Europe/Berlin');
  if (dt.isValid) {
    const fmt = { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' };
    slotUser = dt.setLocale(locale).toLocaleString(fmt);
    slotDe = dt.setLocale('de-DE').toLocaleString(fmt) + ' Uhr';
  }
}
const bring = Array.isArray(b.bring_items) ? b.bring_items.map(x => String(x).slice(0, 80)).slice(0, 10) : [];
const outcome = String(b.outcome || '');
const user = [
  'Target language: ' + LANG[lang] + ' (' + lang + ')',
  'Outcome code: ' + outcome,
  'Booked time (already formatted for the user, copy exactly if relevant): ' + (slotUser || 'none'),
  'Booked time in German: ' + (slotDe || 'none'),
  'Structured result (JSON): ' + JSON.stringify(b.result ?? null).slice(0, 1500),
  'English summary from the call: ' + String(b.summary_en || '').slice(0, 1500),
  'German items to bring (JSON): ' + JSON.stringify(bring)
].join('\n');
return { json: { call_id: b.call_id, request_id: b.request_id, outcome, lang, bring, user_prompt: user } };

// Parse Claude JSON -> summary_user + bring_items_user; decide the request status update.
const prep = $('Prepare Result').item.json;
const raw = ($json.content ?? []).filter(c => c.type === 'text').map(c => c.text).join('\n').trim();
const m = raw.match(/\{[\s\S]*\}/);
if (!m) throw new Error('no JSON in result');
const t = JSON.parse(m[0]);
const summary = String(t.summary_user || '').trim().slice(0, 1200);
if (!summary) throw new Error('empty summary_user');
const items = (Array.isArray(t.bring_items_user) ? t.bring_items_user : [])
  .filter(i => i && i.de)
  .slice(0, 10)
  .map(i => ({ de: String(i.de).slice(0, 80), meaning_user: String(i.meaning_user || '').slice(0, 160) }));
// only final successful outcomes move the request; needs_user/rejected/failed are never overwritten (URL filter)
const STATUS_FOR = { booked: 'booked', completed: 'completed' };
return { json: { call_id: prep.call_id, request_id: prep.request_id, outcome: prep.outcome, lang: prep.lang,
  summary_user: summary, bring_items_user: items, new_status: STATUS_FOR[prep.outcome] || '' } };
